// HasStructure applies the HasEdge predicate on the "structure" edge.
func HasStructure() predicate.Unit {
	return predicate.Unit(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, StructureTable, StructureColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasStructureWith applies the HasEdge predicate on the "structure" edge with a given conditions (other predicates).
func HasStructureWith(preds ...predicate.Structure) predicate.Unit {
	return predicate.Unit(func(s *sql.Selector) {
		step := newStructureStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

